#include "scene.hpp"


using namespace cgp;


// Main initialization function called once at program startup
// Sets up the camera, 3D scene elements, and the image animation system
void scene_structure::initialize()
{
	
	std::cout << "Start function scene_structure::initialize()" << std::endl;

	// Set the behavior of the camera and its initial position
	// ********************************************** //
	camera_control.initialize(inputs, window); 
	camera_control.set_rotation_axis_z(); // camera rotates around z-axis
	//   look_at(camera_position, targeted_point, up_direction)
	camera_control.look_at(
		{ 3.0f, -2.0f, 1.5f } /* position of the camera in the 3D scene */,
		{0,0,0} /* targeted point in 3D scene */,
		{0,0,1} /* direction of the "up" vector */);


	// General information
	display_info();

	// Create 3D coordinate frame (x, y, z axes) for visual reference
	global_frame.initialize_data_on_gpu(mesh_primitive_frame());

	// Initialize the shapes of the scene
	// ***************************************** //

	gui.display_frame = true;

	sphere.initialize_data_on_gpu(mesh_primitive_sphere(0.25f));
	sphere.model.translation = {-0.5f, 0.75f, 0.0f};
	sphere.material.color = {1.0f, 0.0f, 0.0f};

	cylinder.initialize_data_on_gpu(mesh_primitive_cylinder(0.1f,{0,0,-0.5f},{0,0,0.5f}));
	cylinder.model.translation = {0.5f, -0.75f, 0.0f};
	cylinder.material.color = {0.0f, 1.0f, 0.0f};


image_structure const image_skybox = image_load_file(project::path + "assets/skybox_01.jpg");

// Cut the cross into 4 x 3 squares: faces[row + 3*column]
std::vector<image_structure> faces = image_split_grid(image_skybox, 4, 3);

skybox.initialize_data_on_gpu();
skybox.texture.initialize_cubemap_on_gpu(
    faces[1],  faces[7],    // -x, +x
    faces[5],  faces[3],    // -y, +y
    faces[10], faces[4]);   // -z, +z

// The cube map is y-up (OpenGL convention), the default scene is z-up: tilt the sky
skybox.skybox_rotation = rotation_transform::from_axis_angle({1,0,0}, -Pi / 2).matrix();

torus.initialize_data_on_gpu(mesh_primitive_torus());
torus.model.translation = {0, 0, 1.0f};   // above the sphere and the cylinder of the template
torus.shader.load(
    project::path + "shaders/mesh/mesh.vert.glsl",
    project::path + "shaders/environment_map/environment_map.frag.glsl");

torus.supplementary_texture["image_skybox"] = skybox.texture;     // name of the GLSL sampler
uniforms_reflection.uniform_mat3["skybox_rotation"] = skybox.skybox_rotation;

	std::cout << "End function scene_structure::initialize()" << std::endl;
}




// This function is called permanently at every new frame
// Note that you should avoid having costly computation and large allocation defined there. This function is mostly used to call the draw() functions on pre-existing data.
void scene_structure::display_frame()
{
    environment.camera_view = camera_control.camera().matrix_view();
    environment.light = camera_control.camera_model.position();

    glDepthMask(GL_FALSE);          // do not write the depth: the sky stays behind everything
    draw(skybox, environment);
    glDepthMask(GL_TRUE);

    if (gui.display_frame)          // then the shapes of the scene
        draw(global_frame, environment);
    draw(sphere, environment);
    cylinder.model.rotation = rotation_transform::from_axis_angle({1,0,0}, timer.t);
    draw(cylinder, environment);

draw(torus, environment, 1, true, uniforms_reflection);   // extra uniforms for this shape only

    timer.update();
}


void scene_structure::display_gui()
{

	ImGui::Checkbox("Frame", &gui.display_frame);
}




void scene_structure::mouse_move_event()
{
	if (!inputs.keyboard.shift)
		camera_control.action_mouse_move();
	
}
void scene_structure::mouse_click_event()
{
	camera_control.action_mouse_click();
}
void scene_structure::keyboard_event()
{
	camera_control.action_keyboard();
}
void scene_structure::idle_frame()
{
	camera_control.idle_frame();
	
}

void scene_structure::display_info()
{
	std::cout << "\nCAMERA CONTROL:" << std::endl;
	std::cout << "-----------------------------------------------" << std::endl;
	std::cout << camera_control.doc_usage() << std::endl;
	std::cout << "-----------------------------------------------\n" << std::endl;


	std::cout << "\nSCENE INFO:" << std::endl;
	std::cout << "-----------------------------------------------" << std::endl;
	std::cout << "Introduction test scene." << std::endl;
	std::cout << "-----------------------------------------------\n" << std::endl;
}